/**
 * 沉浸式阅读页：书架点开一本书之后的阅读空间。
 *
 * 这一版把「标注」和「词典」从独立入口改成阅读过程中自然浮出的工具：
 *   选中文字 → 浮动工具条（高亮三色 / 笔记 / AI 解释 / 存知识卡）
 *   点击单词 → 轻量词典卡片（要理解用法再去右侧 AI 面板）
 * 页面上没有常驻的标注工具栏，正文两侧不挂按钮。
 *
 * 标注存的是「段落下标 + 字符区间」，渲染时按 token 落色；DOM 里每个段落的
 * textContent 和 readerParagraphText() 完全一致，选区换算出来的偏移才对得上。
 */
import { ArrowLeft, BookOpen, Languages } from "lucide-react";
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type MouseEvent as ReactMouseEvent,
} from "react";
import { Navigate, useNavigate, useParams } from "react-router-dom";
import { appendLocalDrawerNote } from "../../lib/drawerNotes";
import { cn } from "../../lib/cn";
import {
  tokenizeReaderTextWithOffsets,
  type ReaderTextTokenRange,
} from "../../lib/readerWords";
import {
  annotationAtOffset,
  annotationsByColor,
  insertReaderAnnotation,
  loadReaderAnnotations,
  paragraphAnnotations,
  readerParagraphText,
  removeReaderAnnotation,
  saveReaderAnnotations,
  updateReaderAnnotation,
  type ReaderAnnotation,
  type ReaderAnnotations,
  type ReaderHighlightColor,
} from "../../lib/readerAnnotations";
import {
  allReaderBooks,
  readerBookById,
  type ReaderBook,
} from "../../lib/readerLibrary";
import { createId } from "../../lib/createId";
import { useLeafia } from "../../store/leafia";
import {
  ReaderInsightPanel,
  type ReaderInsightRequest,
} from "../reader/ReaderInsightPanel";
import { ReaderSelectionToolbar } from "../reader/ReaderSelectionToolbar";
import { WordLookupFolder } from "../reader/WordLookupFolder";
import { useReaderActions } from "../reader/useReaderActions";
import { SplitText } from "../reactbits/vendor";
import { PageFlipReader } from "./PageFlipReader";
import "./immersive-reader.css";

interface SelectionRange {
  paragraphIndex: number;
  start: number;
  end: number;
  text: string;
}

interface SelectionState {
  ranges: SelectionRange[];
  text: string;
  x: number;
  y: number;
  placement: "above" | "below";
  paragraphIndex: number;
  /** 选中的文字上已有的标注，有值时工具条进入编辑态。 */
  annotation: ReaderAnnotation | null;
}

interface LookupState {
  word: string;
  contextBefore: string;
  contextAfter: string;
  x: number;
  y: number;
  drawer: boolean;
}

const CONTEXT_SPAN = 180;

function splitParagraphs(value: string) {
  return value
    .split(/\n+/)
    .map((paragraph) => paragraph.trim())
    .filter(Boolean);
}

/** 选中区间前后的上下文，交给 AI 判断「在这里为什么这样用」。 */
function contextAround(text: string, start: number, end: number) {
  return {
    before: text.slice(Math.max(0, start - CONTEXT_SPAN), start),
    after: text.slice(end, end + CONTEXT_SPAN),
  };
}

/** 选区从某个节点起算了多少个字符（段落里的下标）。 */
function offsetWithin(element: HTMLElement, node: Node, offset: number) {
  const probe = document.createRange();
  probe.selectNodeContents(element);
  probe.setEnd(node, offset);
  return probe.toString().length;
}

function closestParagraph(node: Node | null): HTMLElement | null {
  const element =
    node && node.nodeType === Node.ELEMENT_NODE
      ? (node as Element)
      : node?.parentElement;
  return (element?.closest("[data-paragraph]") as HTMLElement | null) ?? null;
}

/**
 * 把浏览器的选区换算成段落区间。跨段选中会得到多段，每段各存一条标注。
 * 首尾的空白不属于标注，先收掉。
 */
function collectSelectionRanges(
  source: HTMLElement,
  range: Range,
): SelectionRange[] {
  const startParagraph = closestParagraph(range.startContainer);
  const endParagraph = closestParagraph(range.endContainer);
  if (!startParagraph || !endParagraph) return [];
  if (!source.contains(startParagraph) || !source.contains(endParagraph)) {
    return [];
  }
  // 翻页阅读器在正文里放了一份「量高度用」的副本（data-measure），
  // 那份不是正文，不能进选区换算的队列。
  const paragraphs = Array.from(
    source.querySelectorAll<HTMLElement>("[data-paragraph]"),
  ).filter((element) => !element.closest("[data-measure]"));
  const startIndex = paragraphs.indexOf(startParagraph);
  const endIndex = paragraphs.indexOf(endParagraph);
  if (startIndex < 0 || endIndex < startIndex) return [];

  const ranges: SelectionRange[] = [];
  for (let index = startIndex; index <= endIndex; index += 1) {
    const element = paragraphs[index];
    if (!element) continue;
    const paragraphIndex = Number(element.dataset.paragraph);
    if (!Number.isFinite(paragraphIndex)) continue;
    const full = element.textContent ?? "";
    let start = element.contains(range.startContainer)
      ? offsetWithin(element, range.startContainer, range.startOffset)
      : 0;
    let end = element.contains(range.endContainer)
      ? offsetWithin(element, range.endContainer, range.endOffset)
      : full.length;
    start = Math.max(0, Math.min(start, full.length));
    end = Math.max(0, Math.min(end, full.length));
    while (start < end && /\s/.test(full[start] ?? "")) start += 1;
    while (end > start && /\s/.test(full[end - 1] ?? "")) end -= 1;
    if (end <= start) continue;
    ranges.push({
      paragraphIndex,
      start,
      end,
      text: full.slice(start, end),
    });
  }
  return ranges;
}

function annotationOverlapping(
  entries: ReaderAnnotation[],
  start: number,
  end: number,
) {
  return (
    entries.find(
      (annotation) => annotation.start < end && annotation.end > start,
    ) ?? null
  );
}

export function BookReaderPage() {
  const { bookId } = useParams();
  const navigate = useNavigate();
  const sourceRef = useRef<HTMLElement>(null);
  const showToast = useLeafia((state) => state.showToast);
  const [showTranslation, setShowTranslation] = useState(false);
  const [annotations, setAnnotations] = useState<ReaderAnnotations>({});
  const [selection, setSelection] = useState<SelectionState | null>(null);
  const [lookup, setLookup] = useState<LookupState | null>(null);
  const [insightRequest, setInsightRequest] =
    useState<ReaderInsightRequest | null>(null);

  const book = useMemo(() => readerBookById(bookId ?? ""), [bookId]);
  const sourceParagraphs = useMemo(
    () => splitParagraphs(book?.source ?? ""),
    [book],
  );
  const paragraphTexts = useMemo(
    () => sourceParagraphs.map(readerParagraphText),
    [sourceParagraphs],
  );
  const translationParagraphs = useMemo(
    () => splitParagraphs(book?.translation ?? ""),
    [book],
  );
  const { saveKnowledgeCard } = useReaderActions({
    bookId: book?.id ?? "",
    bookLabel: book?.zhTitle ?? "",
  });

  useEffect(() => {
    setSelection(null);
    setLookup(null);
    setInsightRequest(null);
    setAnnotations(
      bookId ? loadReaderAnnotations(bookId, sourceParagraphs) : {},
    );
  }, [bookId, sourceParagraphs]);

  const commit = useCallback(
    (next: ReaderAnnotations) => {
      setAnnotations(next);
      if (bookId) saveReaderAnnotations(bookId, next);
    },
    [bookId],
  );

  const dismissSelection = useCallback(() => {
    setSelection(null);
    window.getSelection()?.removeAllRanges();
  }, []);

  const captureSelection = useCallback(() => {
    const browserSelection = window.getSelection();
    const source = sourceRef.current;
    if (!browserSelection || browserSelection.isCollapsed || !source) return;
    if (browserSelection.rangeCount === 0) return;

    const range = browserSelection.getRangeAt(0);
    const ranges = collectSelectionRanges(source, range);
    if (ranges.length === 0) {
      setSelection(null);
      return;
    }
    const text = ranges.map((entry) => entry.text).join(" ");
    if (text.length > 300) {
      setSelection(null);
      return;
    }

    const rect = range.getBoundingClientRect();
    if (rect.width === 0 && rect.height === 0) return;
    const placeAbove = rect.top > 140;
    const half = Math.min(190, window.innerWidth / 2);
    const x = Math.max(half + 8, Math.min(window.innerWidth - half - 8, rect.left + rect.width / 2));
    const existing =
      ranges.length === 1
        ? annotationAtOffset(
            annotations,
            ranges[0]!.paragraphIndex,
            ranges[0]!.start,
          )
        : null;

    setSelection({
      ranges,
      text,
      x,
      y: placeAbove ? rect.top - 10 : rect.bottom + 10,
      placement: placeAbove ? "above" : "below",
      paragraphIndex: ranges[0]!.paragraphIndex,
      annotation: existing,
    });
  }, [annotations]);

  if (!book) return <Navigate to="/library" replace />;

  const buildAnnotation = (
    range: SelectionRange,
    patch: Partial<Pick<ReaderAnnotation, "color" | "note">>,
  ): ReaderAnnotation => ({
    id: createId(),
    color: patch.color ?? null,
    note: patch.note,
    text: range.text,
    start: range.start,
    end: range.end,
    createdAt: new Date().toISOString(),
  });

  const applyHighlight = (color: ReaderHighlightColor) => {
    if (!selection) return;
    if (selection.annotation) {
      commit(
        updateReaderAnnotation(
          annotations,
          selection.paragraphIndex,
          selection.annotation.id,
          { color },
        ),
      );
    } else {
      let next = annotations;
      for (const range of selection.ranges) {
        next = insertReaderAnnotation(
          next,
          range.paragraphIndex,
          buildAnnotation(range, { color }),
        );
      }
      commit(next);
    }
    dismissSelection();
  };

  const saveNote = (note: string, { toDrawer }: { toDrawer: boolean }) => {
    if (!selection) return;
    if (selection.annotation) {
      commit(
        updateReaderAnnotation(
          annotations,
          selection.paragraphIndex,
          selection.annotation.id,
          { note },
        ),
      );
    } else {
      const range = selection.ranges[0];
      if (!range) return;
      commit(
        insertReaderAnnotation(
          annotations,
          range.paragraphIndex,
          buildAnnotation(range, { note }),
        ),
      );
    }
    if (toDrawer) {
      const added = appendLocalDrawerNote({
        drawerId: "notes",
        title: `「${selection.text.slice(0, 56)}」`,
        meta: `${book.zhTitle} · 阅读批注`,
      });
      showToast(
        added
          ? "笔记已留在书页，并沉入书架抽屉 · Notes"
          : "抽屉便条已满（每格 3 张），这条笔记只存在书页上。",
      );
    } else {
      showToast("笔记已记在这段文字上");
    }
    dismissSelection();
  };

  const explainSelection = () => {
    if (!selection) return;
    const first = selection.ranges[0];
    const paragraph = paragraphTexts[first?.paragraphIndex ?? -1] ?? "";
    const context = first
      ? contextAround(paragraph, first.start, first.end)
      : { before: "", after: "" };
    setInsightRequest({
      kind: "selection",
      text: selection.text,
      contextBefore: context.before,
      contextAfter: context.after,
    });
    dismissSelection();
  };

  const saveCardFromSelection = () => {
    if (!selection) return;
    const first = selection.ranges[0];
    const paragraph = paragraphTexts[first?.paragraphIndex ?? -1] ?? "";
    const context = first
      ? contextAround(paragraph, first.start, first.end)
      : { before: "", after: "" };
    void saveKnowledgeCard({
      term: selection.text,
      contextBefore: context.before,
      contextAfter: context.after,
    });
    dismissSelection();
  };

  const removeSelectionAnnotation = () => {
    if (!selection?.annotation) return;
    commit(
      removeReaderAnnotation(
        annotations,
        selection.paragraphIndex,
        selection.annotation.id,
      ),
    );
    dismissSelection();
  };

  const openWord = (
    event: ReactMouseEvent<HTMLButtonElement>,
    paragraphIndex: number,
    token: ReaderTextTokenRange,
  ) => {
    const rect = event.currentTarget.getBoundingClientRect();
    const paragraph = paragraphTexts[paragraphIndex] ?? "";
    const existing = annotationAtOffset(annotations, paragraphIndex, token.start);
    const placeAbove = rect.top > 140;
    const half = Math.min(190, window.innerWidth / 2);
    const x = Math.max(
      half + 8,
      Math.min(window.innerWidth - half - 8, rect.left + rect.width / 2),
    );
    if (existing) {
      setLookup(null);
      setSelection({
        ranges: [
          {
            paragraphIndex,
            start: existing.start,
            end: existing.end,
            text: existing.text,
          },
        ],
        text: existing.text,
        x,
        y: placeAbove ? rect.top - 10 : rect.bottom + 10,
        placement: placeAbove ? "above" : "below",
        paragraphIndex,
        annotation: existing,
      });
      return;
    }
    const context = contextAround(paragraph, token.start, token.end);
    setSelection(null);
    setLookup({
      word: token.value,
      contextBefore: context.before,
      contextAfter: context.after,
      x: Math.max(12, Math.min(window.innerWidth - 392, rect.left - 20)),
      y: Math.min(
        window.innerHeight - 560,
        placeAbove ? rect.top - 300 : rect.bottom + 12,
      ),
      drawer: window.innerWidth < 720,
    });
  };

  const counts = annotationsByColor(annotations);
  const highlightCount = counts.yellow + counts.blue + counts.purple;

  // 正文切成一块一块交给翻页阅读器去分页：分页只整块搬，不切开段落，
  // 标注存的「段落下标 + 字符区间」才对得上。
  const paragraphLeaves = sourceParagraphs.map((_, index) => {
    const entries = paragraphAnnotations(annotations, index);
    return (
      <section key={`${book.id}-${index}`}>
        <p className="immersive-reader__paragraph" data-paragraph={index}>
          {tokenizeReaderTextWithOffsets(paragraphTexts[index] ?? "").map(
            (token, tokenIndex) => {
              const hit = annotationOverlapping(
                entries,
                token.start,
                token.end,
              );
              const noteStart = entries.find(
                (entry) =>
                  entry.note && token.start <= entry.start && entry.start < token.end,
              );
              const className = cn(
                token.isWord && "immersive-reader__word",
                hit?.color && `is-hl-${hit.color}`,
                hit && !hit.color && hit.note && "is-note-line",
                noteStart && "is-noted",
              );
              if (!token.isWord) {
                return (
                  <span
                    key={`${index}-${tokenIndex}-${token.start}`}
                    className={className}
                  >
                    {token.value}
                  </span>
                );
              }
              return (
                <button
                  key={`${index}-${tokenIndex}-${token.start}`}
                  type="button"
                  className={className}
                  onClick={(event) => openWord(event, index, token)}
                >
                  {token.value}
                </button>
              );
            },
          )}
        </p>
        {showTranslation && translationParagraphs[index] && (
          <p className="immersive-reader__translation">
            {translationParagraphs[index]}
          </p>
        )}
      </section>
    );
  });

  return (
    <article className="immersive-reader">
      <header className="immersive-reader__header">
        <button
          type="button"
          onClick={() => navigate("/library")}
          aria-label="返回书架"
        >
          <ArrowLeft size={18} />
        </button>
        <div>
          <span className="eyebrow">{book.author}</span>
          <SplitText
            tag="h1"
            text={book.title}
            className="immersive-reader__title"
            delay={52}
            duration={0.58}
            ease="power3.out"
            splitType="words"
            from={{ opacity: 0, y: 24 }}
            to={{ opacity: 1, y: 0 }}
            threshold={0}
            rootMargin="0px"
            textAlign="left"
          />
          <p>{book.zhTitle}</p>
        </div>
        <button
          type="button"
          className={showTranslation ? "is-active" : ""}
          onClick={() => setShowTranslation((value) => !value)}
          aria-pressed={showTranslation}
        >
          <Languages size={16} />
          中文
        </button>
      </header>

      <div className="immersive-reader__meta">
        <span>{sourceParagraphs.length} paragraphs</span>
        <span>
          {highlightCount > 0 || counts.note > 0
            ? `本页 ${highlightCount} 处高亮 · ${counts.note} 条笔记`
            : "选中文字即可标注 · 点击单词查词典"}
        </span>
        <span>词典 · 点词查义</span>
      </div>

      <main
        ref={sourceRef}
        className="immersive-reader__text"
        onMouseUp={captureSelection}
        onKeyUp={captureSelection}
      >
        <PageFlipReader
          leaves={paragraphLeaves}
          measureKey={`${book.id}-${sourceParagraphs.length}-${showTranslation ? "zh" : "en"}`}
        />
      </main>

      <footer className="immersive-reader__footer">
        <button type="button" onClick={() => navigate("/library")}>
          <BookOpen size={15} />
          书架
        </button>
        <span>
          {Math.max(
            1,
            allReaderBooks().findIndex((entry) => entry.id === book.id) + 1,
          )}{" "}
          / {allReaderBooks().length}
        </span>
      </footer>

      {selection && (
        <ReaderSelectionToolbar
          text={selection.text}
          x={selection.x}
          y={selection.y}
          placement={selection.placement}
          annotation={selection.annotation}
          onHighlight={applyHighlight}
          onSaveNote={saveNote}
          onExplain={explainSelection}
          onSaveCard={saveCardFromSelection}
          onRemove={removeSelectionAnnotation}
          onDismiss={dismissSelection}
        />
      )}

      {lookup && (
        <WordLookupFolder
          word={lookup.word}
          contextBefore={lookup.contextBefore}
          contextAfter={lookup.contextAfter}
          x={lookup.x}
          y={lookup.y}
          drawer={lookup.drawer}
          bookId={book.id}
          bookLabel={book.zhTitle}
          onExplain={(word, contextBefore, contextAfter) => {
            setLookup(null);
            setInsightRequest({
              kind: "word",
              text: word,
              contextBefore,
              contextAfter,
            });
          }}
          onClose={() => setLookup(null)}
        />
      )}

      <ReaderInsightPanel
        request={insightRequest}
        source={{ bookId: book.id, bookLabel: book.zhTitle }}
        onClose={() => setInsightRequest(null)}
      />
    </article>
  );
}
