const pad2 = (value: number) => String(value).padStart(2, "0");

function normalizeAnswer(value: string) {
  return value
    .trim()
    .toLowerCase()
    .replace(/[.!?。！？]+$/g, "")
    .replace(/\s+/g, " ");
}

function isCorrectAnswer(item: PracticeItem, answer: string) {
  const normalized = normalizeAnswer(answer);
  return [item.answer, ...item.acceptedAnswers].some(
    (candidate) => normalizeAnswer(candidate) === normalized,
  );
}

// 教材正文里的层级符（· – ◦ ▪）只做缩进，文字原样保留。
function lineDepth(line: string) {
  if (/^[·•]\s/.test(line)) return 1;
  if (/^[–—]\s/.test(line)) return 2;
  if (/^[◦]\s/.test(line)) return 3;
  if (/^[▪‣]\s/.test(line)) return 4;
  return 0;
}

// 「1.1.1 Definition」这类教材编号行：加粗、上面留白，像小节标题。
function lineIsSection(line: string) {
  return /^\d+(\.\d+)+\s/.test(line);
}

type ReadingPage =
  | { nodeId: string; kind: "intro" }
  | { nodeId: string; kind: "points"; part: number; parts: number }
  | {
      nodeId: string;
      kind: "detail";
      titleZh: string;
      bodyZh: string;
      continued?: boolean;
    };

// 一页最多排约 12 行正文（小节标题按 1.7 行计），排不下的按整行分到下一页。
// 概览页拆成「Definition + Original Text」和「Key points（每页 7 条）+ Keywords」，
// 全书不再上下滚动：靠这里预分页 + 运行时版面自适应，保证每页装得下、一字不丢。
// 行数给得松一点，字号才能保持在「实体书」的尺寸，不被缩排压小。
const READING_LINES_PER_PAGE = 12;
const OVERVIEW_POINTS_PER_PAGE = 7;

function readingPagesForModule(module: KnowledgeModule): ReadingPage[] {
  const pages: ReadingPage[] = [];
  for (const entry of module.nodes) {
    pages.push({ nodeId: entry.id, kind: "intro" });
    const points = entry.keyPoints;
    const parts = Math.max(
      1,
      Math.ceil(points.length / OVERVIEW_POINTS_PER_PAGE),
    );
    if (points.length || entry.terms.length) {
      for (let part = 0; part < parts; part += 1) {
        pages.push({ nodeId: entry.id, kind: "points", part, parts });
      }
    }
    for (const page of entry.pages ?? []) {
      const lines = page.bodyZh
        .split(/\n+/)
        .map((line) => line.trim())
        .filter(Boolean);
      if (lines.length <= READING_LINES_PER_PAGE) {
        pages.push({
          nodeId: entry.id,
          kind: "detail",
          titleZh: page.titleZh,
          bodyZh: lines.join("\n"),
        });
        continue;
      }
      let bucket: string[] = [];
      let weight = 0;
      let chunk = 0;
      const flush = () => {
        if (!bucket.length) return;
        pages.push({
          nodeId: entry.id,
          kind: "detail",
          titleZh: page.titleZh,
          bodyZh: bucket.join("\n"),
          continued: chunk > 0,
        });
        bucket = [];
        weight = 0;
        chunk += 1;
      };
      for (const line of lines) {
        const lineWeight = lineIsSection(line) ? 1.7 : 1;
        if (weight + lineWeight > READING_LINES_PER_PAGE && bucket.length) {
          flush();
        }
        bucket.push(line);
        weight += lineWeight;
      }
      flush();
    }
  }
  return pages;
}

// 整本书 = 一串实体页：封里 → 目录页（超过一章容量就多页）→ 每章「章首页 + 正文页 + 练习页」→ 卡片页。
// 一次翻页 = 翻过一张纸：右页翻到左边后露出下一页，左右两页都会换成新内容。
type BookPage =
  | { kind: "cover" }
  | { kind: "toc"; part: number; parts: number; moduleIds: string[] }
  | { kind: "chapter"; moduleId: string }
  | { kind: "read"; moduleId: string; pageIndex: number }
  | { kind: "practice"; moduleId: string }
  | { kind: "notes" }
  | { kind: "blank" };

type ContextPage = Extract<
  BookPage,
  { kind: "read" } | { kind: "chapter" } | { kind: "practice" }
>;

const TOC_MODULES_PER_PAGE = 9;

function bookPagesFor(
  book: KnowledgeBook,
  readPagesByModule: Map<string, ReadingPage[]>,
): BookPage[] {
  const pages: BookPage[] = [];
  // 第一张纸是封面：正面是封面设计，背面是这张「封里」页。
  pages.push({ kind: "cover" });
  const chunks: string[][] = [];
  for (let i = 0; i < book.modules.length; i += TOC_MODULES_PER_PAGE) {
    chunks.push(
      book.modules.slice(i, i + TOC_MODULES_PER_PAGE).map((module) => module.id),
    );
  }
  if (!chunks.length) chunks.push([]);
  chunks.forEach((moduleIds, index) => {
    pages.push({
      kind: "toc",
      part: index + 1,
      parts: chunks.length,
      moduleIds,
    });
  });
  for (const module of book.modules) {
    pages.push({ kind: "chapter", moduleId: module.id });
    const reads = readPagesByModule.get(module.id) ?? [];
    reads.forEach((_, pageIndex) =>
      pages.push({ kind: "read", moduleId: module.id, pageIndex }),
    );
    pages.push({ kind: "practice", moduleId: module.id });
  }
  pages.push({ kind: "notes" });
  // 书页成对：落单时末尾补一张空白页（实体书也这样）。
  if (pages.length % 2 !== 0) pages.push({ kind: "blank" });
  return pages;
}

function pageIdentity(page: BookPage | undefined): string {
  if (!page) return "none";
  switch (page.kind) {
    case "cover":
      return "cover";
    case "toc":
      return `toc-${page.part}`;
    case "chapter":
      return `chapter-${page.moduleId}`;
    case "read":
      return `read-${page.moduleId}-${page.pageIndex}`;
    case "practice":
      return `practice-${page.moduleId}`;
    case "notes":
      return "notes";
    default:
      return "blank";
  }
}

type LeafTurn = {
  dir: 1 | -1;
  from: number;
  to: number;
  single: boolean;
  // cover：翻开封面；close：读到最后一页把书合上；reopen：从封底再翻开
  special?: "cover" | "close" | "reopen";
};

export function KnowledgeBookPage() {
  const { bookId } = useParams();
  const navigate = useNavigate();
  const book = knowledgeBookById(bookId);
  const hydrate = useKnowledge((state) => state.hydrate);
  const cards = useKnowledge((state) => state.cards);
  const attempts = useKnowledge((state) => state.attempts);
  const addNodeCard = useKnowledge((state) => state.addNodeCard);
  const recordAttempt = useKnowledge((state) => state.recordAttempt);

  // 翻到的位置：spread = 摊开的是第几张纸（左右两页）；pageIndex = 窄屏单页模式的第几页。
  // phase = 书的状态：closed 合着（封面朝上）→ open 翻开 → back 读完合上（封底朝上）。
  const [phase, setPhase] = useState<"closed" | "open" | "back">("closed");
  const [spread, setSpread] = useState(0);
  const [pageIndex, setPageIndex] = useState(0);
  const [single, setSingle] = useState(
    () =>
      typeof window !== "undefined" &&
      window.matchMedia("(max-width: 980px)").matches,
  );
  const [turn, setTurn] = useState<LeafTurn | null>(null);
  const turnRef = useRef<LeafTurn | null>(null);
  const bookRef = useRef<HTMLDivElement | null>(null);

  const [selectedModuleId, setSelectedModuleId] = useState<string | null>(null);
  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
  const [practiceIndex, setPracticeIndex] = useState(0);
  const [answer, setAnswer] = useState("");
  const [feedback, setFeedback] = useState<string | null>(null);
  const [feedbackCorrect, setFeedbackCorrect] = useState<boolean | null>(null);
  // 知识卡片：读到的这一页随手写一张，卡片归到这本书下面。
  const [notes, setNotes] = useState(loadKnowledgeNotes);
  const [noteDraft, setNoteDraft] = useState("");
  const [noteIndex, setNoteIndex] = useState(0);

  useEffect(() => {
    void hydrate();
  }, [hydrate]);

  const readPagesByModule = useMemo(() => {
    const map = new Map<string, ReadingPage[]>();
    if (book) {
      for (const module of book.modules) {
        map.set(module.id, readingPagesForModule(module));
      }
    }
    return map;
  }, [book]);

  const pages = useMemo(
    () => (book ? bookPagesFor(book, readPagesByModule) : []),
    [book, readPagesByModule],
  );

  const totalLeaves = single ? pages.length : Math.ceil(pages.length / 2);
  const position = single ? pageIndex : spread;
  const safePos = totalLeaves
    ? Math.min(Math.max(position, 0), totalLeaves - 1)
    : 0;

  // 静态展示的两页：翻页动画进行中，翻去的方向决定哪一边先换成新内容。
  const staticLeftPos = !turn ? safePos : turn.dir === 1 ? turn.from : turn.to;
  const staticRightPos = !turn ? safePos : turn.dir === 1 ? turn.to : turn.from;
  const staticLeftPage = single ? undefined : pages[2 * staticLeftPos];
  const staticRightPage = single ? pages[safePos] : pages[2 * staticRightPos + 1];

  // 翻动的那张纸：正面 = 抬起来的那页（前进时是旧右页 / 后退时是新右页），
  // 背面 = 落到左边的那页（前进时是新左页 / 后退时是当前左页）。
  const faceFront = !turn
    ? undefined
    : single
      ? pages[turn.dir === 1 ? turn.from : turn.to]
      : pages[2 * (turn.dir === 1 ? turn.from : turn.to) + 1];
  const faceBack =
    !turn || single
      ? undefined
      : pages[2 * (turn.dir === 1 ? turn.to : turn.from)];

  // 正在读的上下文：以摊开页里的正文/章首/练习页为准，锁存给卡片与练习用。
  const contextPage = useMemo<ContextPage | undefined>(() => {
    const pick = (page: BookPage | undefined): ContextPage | undefined =>
      page &&
      (page.kind === "read" ||
        page.kind === "chapter" ||
        page.kind === "practice")
        ? page
        : undefined;
    const right = single ? pages[safePos] : pages[2 * safePos + 1];
    const left = single ? undefined : pages[2 * safePos];
    return pick(right) ?? pick(left);
  }, [pages, safePos, single]);

  const readDataFor = useCallback(
    (page: { moduleId: string; pageIndex: number }) => {
      const module =
        book?.modules.find((entry) => entry.id === page.moduleId) ??
        book?.modules[0];
      const list = readPagesByModule.get(page.moduleId) ?? [];
      const safeIndex = list.length
        ? Math.min(Math.max(page.pageIndex, 0), list.length - 1)
        : 0;
      const readingPage = list[safeIndex];
      const node =
        module?.nodes.find((entry) => entry.id === readingPage?.nodeId) ??
        module?.nodes[0];
      const nodeIndex = module
        ? Math.max(
            0,
            module.nodes.findIndex((entry) => entry.id === node?.id),
          )
        : 0;
      return { module, list, safeIndex, readingPage, node, nodeIndex };
    },
    [book, readPagesByModule],
  );

  useEffect(() => {
    if (!book) return;
    recordStudyEvent({ kind: "open", at: Date.now(), bookId: book.id });
    setPhase("closed");
    setSpread(0);
    setPageIndex(0);
    setSelectedModuleId(book.modules[0]?.id ?? null);
    setSelectedNodeId(book.modules[0]?.nodes[0]?.id ?? null);
  }, [book]);

  // 真正翻到新的一对页面时，更新「正在读」的章节/知识点，并复位练习作答。
  const contextId = pageIdentity(contextPage);
  useEffect(() => {
    if (!book || !contextPage) return;
    if (contextPage.kind === "read") {
      const data = readDataFor(contextPage);
      if (data.module) setSelectedModuleId(data.module.id);
      setSelectedNodeId(data.node?.id ?? null);
    } else {
      const module = book.modules.find(
        (entry) => entry.id === contextPage.moduleId,
      );
      setSelectedModuleId(module?.id ?? null);
      setSelectedNodeId(module?.nodes[0]?.id ?? null);
    }
    setPracticeIndex(0);
    setAnswer("");
    setFeedback(null);
    setFeedbackCorrect(null);
  }, [book, contextId, contextPage, readDataFor]);

  // 打开封面：封面那张纸从右边翻到左边，背面（封里）正好落在左页上。
  const openBook = useCallback(() => {
    if (phase !== "closed" || turnRef.current || !pages.length) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setPhase("open");
      return;
    }
    const leaf: LeafTurn = { dir: 1, from: 0, to: 0, single, special: "cover" };
    turnRef.current = leaf;
    setTurn(leaf);
  }, [phase, pages.length, single]);

  // 读到最后一页再往后翻 = 把书合上：最后一张纸翻过去，背面就是封底（独立的一面）。
  // 窄屏单页不做翻纸动画，直接换到封底那一面。
  const closeBook = useCallback(() => {
    if (phase !== "open" || turnRef.current || !pages.length) return;
    if (
      single ||
      window.matchMedia("(prefers-reduced-motion: reduce)").matches
    ) {
      setPhase("back");
      return;
    }
    const from = single ? pageIndex : spread;
    const leaf: LeafTurn = {
      dir: 1,
      from,
      to: from,
      single,
      special: "close",
    };
    turnRef.current = leaf;
    setTurn(leaf);
  }, [phase, pages.length, single, pageIndex, spread]);

  // 从封底再翻开：封底那张纸摆回右边，回到最后一对页。
  const reopenFromBack = useCallback(() => {
    if (phase !== "back" || turnRef.current || !pages.length) return;
    if (
      single ||
      window.matchMedia("(prefers-reduced-motion: reduce)").matches
    ) {
      setPhase("open");
      return;
    }
    const from = single ? pageIndex : spread;
    const leaf: LeafTurn = {
      dir: -1,
      from,
      to: from,
      single,
      special: "reopen",
    };
    turnRef.current = leaf;
    setTurn(leaf);
  }, [phase, pages.length, single, pageIndex, spread]);

  const beginTurn = useCallback(
    (to: number, dir: 1 | -1) => {
      if (turnRef.current || !pages.length) return;
      // 书还合着：往后翻的动作都先变成翻开封面；封底朝上时向左翻 = 再翻开。
      if (phase === "closed") {
        openBook();
        return;
      }
      if (phase === "back") {
        if (dir === -1) reopenFromBack();
        return;
      }
      const from = single ? pageIndex : spread;
      // 翻到最后一对页还往后翻：合上书。
      if (dir === 1 && from === totalLeaves - 1) {
        closeBook();
        return;
      }
      if (to === from || to < 0 || to >= totalLeaves) return;
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        if (single) setPageIndex(to);
        else setSpread(to);
        return;
      }
      const leaf: LeafTurn = { dir, from, to, single };
      turnRef.current = leaf;
      setTurn(leaf);
      // 前进：先把新页垫到下面（被翻动的纸盖住），翻完即无缝；后退：翻到落位再换。
      if (dir === 1) {
        if (single) setPageIndex(to);
        else setSpread(to);
      }
    },
    [
      pages.length,
      phase,
      openBook,
      reopenFromBack,
      closeBook,
      single,
      pageIndex,
      spread,
      totalLeaves,
    ],
  );

  const endTurn = useCallback(() => {
    const leaf = turnRef.current;
    if (!leaf) return;
    turnRef.current = null;
    setTurn(null);
    if (leaf.special === "cover" || leaf.special === "reopen") {
      setPhase("open");
      return;
    }
    if (leaf.special === "close") {
      setPhase("back");
      return;
    }
    if (leaf.dir === -1) {
      if (leaf.single) setPageIndex(leaf.to);
      else setSpread(leaf.to);
    }
  }, []);

  // 兜底：万一动画事件没到（切后台等），1.4s 后也要落位。
  useEffect(() => {
    if (!turn) return;
    const timer = window.setTimeout(() => endTurn(), 1400);
    return () => window.clearTimeout(timer);
  }, [turn, endTurn]);

  const flipRef = useRef<(dir: 1 | -1) => void>(() => {});
  flipRef.current = (dir) => {
    beginTurn((single ? pageIndex : spread) + dir, dir);
  };

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.metaKey || event.ctrlKey || event.altKey || event.defaultPrevented)
        return;
      const target = event.target as HTMLElement | null;
      if (
        target &&
        (target.tagName === "INPUT" ||
          target.tagName === "TEXTAREA" ||
          target.tagName === "SELECT" ||
          target.isContentEditable)
      ) {
        return;
      }
      if (event.key === "ArrowRight") flipRef.current(1);
      else if (event.key === "ArrowLeft") flipRef.current(-1);
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);

  // 窄屏/宽屏切换：收起翻页动画，把位置对齐到同一条内容上。
  const modeRef = useRef(single);
  useEffect(() => {
    const media = window.matchMedia("(max-width: 980px)");
    const onChange = () => {
      turnRef.current = null;
      setTurn(null);
      setSingle(media.matches);
    };
    media.addEventListener("change", onChange);
    return () => media.removeEventListener("change", onChange);
  }, []);

  useLayoutEffect(() => {
    if (modeRef.current === single) return;
    modeRef.current = single;
    if (single) {
      setPageIndex(Math.min(2 * spread + 1, Math.max(0, pages.length - 1)));
    } else {
      setSpread(Math.floor(pageIndex / 2));
    }
  }, [single, spread, pageIndex, pages.length]);

  // 版面自适应：量一量每个页槽里的内容，高的按比例缩到装得下（最多缩到 0.62）。
  const fitScales = useRef(new Map<string, number>());
  const applyFit = useCallback(() => {
    const root = bookRef.current;
    if (!root) return;
    root.querySelectorAll<HTMLElement>("[data-fit]").forEach((el) => {
      const key = el.dataset.fit;
      if (!key) return;
      const parent = el.parentElement;
      if (!parent) return;
      el.style.zoom = "";
      const known = fitScales.current.get(key);
      if (known !== undefined) {
        if (known < 1) el.style.zoom = String(known);
        return;
      }
      const styles = window.getComputedStyle(parent);
      const available =
        parent.clientHeight -
        (Number.parseFloat(styles.paddingTop) || 0) -
        (Number.parseFloat(styles.paddingBottom) || 0);
      const needed = el.scrollHeight + 2;
      if (available < 40 || needed < 40) return; // 还没布局（jsdom / 隐藏页）
      const scale =
        needed <= available ? 1 : Math.max(0.62, (available - 4) / needed);
      fitScales.current.set(key, scale);
      if (scale < 1) el.style.zoom = String(scale);
    });
  }, []);

  useLayoutEffect(() => {
    applyFit();
  }, [applyFit, safePos, turn, single, pages.length]);

  useEffect(() => {
    let disposed = false;
    const refit = () => {
      if (!disposed) applyFit();
    };
    if (document.fonts?.ready) {
      void document.fonts.ready
        .then(() => {
          fitScales.current.clear();
          refit();
        })
        .catch(() => {});
    }
    const onResize = () => {
      fitScales.current.clear();
      refit();
    };
    window.addEventListener("resize", onResize);
    return () => {
      disposed = true;
      window.removeEventListener("resize", onResize);
    };
  }, [applyFit]);

  const selectedModule = useMemo(
    () =>
      book?.modules.find((module) => module.id === selectedModuleId) ??
      book?.modules[0],
    [book, selectedModuleId],
  );
  const nodes = useMemo(() => (book ? nodesForBook(book) : []), [book]);
  const selectedNode =
    nodes.find((node) => node.id === selectedNodeId) ??
    selectedModule?.nodes[0];
  const chapterIndex =
    book && selectedModule
      ? Math.max(
          0,
          book.modules.findIndex((module) => module.id === selectedModule.id),
        )
      : 0;

  // 练习题目：站在练习页上时，练的就是这一章的题。
  const practiceItems = useMemo(() => {
    if (!book || !selectedModule) return [];
    if (contextPage?.kind === "practice") {
      return selectedModule.nodes.flatMap((node) => node.practice);
    }
    if (selectedNodeId) {
      return nodes.find((node) => node.id === selectedNodeId)?.practice ?? [];
    }
    return [];
  }, [book, selectedModule, contextPage, selectedNodeId, nodes]);

  if (!book || !pages.length) return <Navigate to="/library" replace />;

  // 封面正面的内容：和书架上的书卡封面同款（分类 / 书名 / 中文名）。
  const coverFace = (
    <div className="book-cover__face">
      <small>{book.categoryId}</small>
      <strong>{book.title}</strong>
      <em>{book.zhTitle}</em>
      <span className="book-cover__hint">轻点翻开</span>
    </div>
  );

  // 封底：读到最后一页再往后翻，合上以后朝上的那一面（也是一面，不是对开）。
  const backCoverFace = (
    <div className="book-cover__face book-cover__face--back">
      <small>{book.categoryId}</small>
      <strong>{book.title}</strong>
      <em>{book.zhTitle}</em>
      <span className="book-cover__hint">读完了 · 轻点再翻开</span>
    </div>
  );

  const moduleById = (id: string) => book.modules.find((module) => module.id === id);
  const leafOfPage = (index: number) => (single ? index : Math.floor(index / 2));
  const jumpToPosition = (target: number) => {
    const from = single ? pageIndex : spread;
    if (target === from) return;
    beginTurn(target, target > from ? 1 : -1);
  };
  const jumpToChapter = (moduleId: string) => {
    const index = pages.findIndex(
      (page) => page.kind === "chapter" && page.moduleId === moduleId,
    );
    if (index >= 0) jumpToPosition(leafOfPage(index));
  };
  const jumpToNode = (moduleId: string, nodeId: string) => {
    const reads = readPagesByModule.get(moduleId) ?? [];
    const readIndex = reads.findIndex((page) => page.nodeId === nodeId);
    if (readIndex < 0) return;
    const index = pages.findIndex(
      (page) =>
        page.kind === "read" &&
        page.moduleId === moduleId &&
        page.pageIndex === readIndex,
    );
    if (index >= 0) jumpToPosition(leafOfPage(index));
  };

  const bookCards = cards.filter((card) => card.bookId === book.id);
  const bookAttempts = knowledgeAttemptsForBook(attempts, book.id);
  const correctAttempts = bookAttempts.filter((attempt) => attempt.correct).length;
  const accuracy = bookAttempts.length
    ? Math.round((correctAttempts / bookAttempts.length) * 100)
    : 0;
  const progress = knowledgeMasteryByBook(cards, book.id);
  const currentPractice = practiceItems[practiceIndex];
  const bookNotes = notes[book.id] ?? [];
  const noteTitles = new Map(nodes.map((node) => [node.id, node.titleZh || node.title]));
  const noteCards = bookNotes.map((note) => ({
    id: note.id,
    title: note.title || "未命名的卡片",
    body: note.body,
    meta: `${noteTitles.get(note.nodeId) ?? "知识卡片"} · ${new Date(
      note.createdAt,
    ).toLocaleDateString("zh-CN")}`,
  }));

  const saveNote = () => {
    const body = noteDraft.trim();
    if (!body || !selectedNode || !selectedModule) return;
    const note = createKnowledgeNote({
      bookId: book.id,
      moduleId: selectedModule.id,
      nodeId: selectedNode.id,
      title: selectedNode.titleZh || selectedNode.title,
      body: body.slice(0, 480),
    });
    setNotes((current) => {
      const next = {
        ...current,
        [book.id]: [note, ...(current[book.id] ?? [])],
      };
      saveKnowledgeNotes(next);
      return next;
    });
    setNoteDraft("");
    setNoteIndex(0);
    // 写卡片也是一次学习动作：记进台账，这本书会浮到「当前学习」。
    recordStudyEvent({
      kind: "topic",
      at: Date.now(),
      bookId: book.id,
      topic: selectedNode.title,
    });
  };

  const removeNote = (noteId: string) => {
    setNotes((current) => {
      const next = {
        ...current,
        [book.id]: (current[book.id] ?? []).filter((note) => note.id !== noteId),
      };
      saveKnowledgeNotes(next);
      return next;
    });
    setNoteIndex(0);
  };

  const submitPractice = () => {
    if (!currentPractice || !answer.trim()) return;
    const correct = isCorrectAnswer(currentPractice, answer);
    setFeedbackCorrect(correct);
    setFeedback(
      `${correct ? "Correct. " : "Not quite. "}${currentPractice.explanationZh}`,
    );
    recordAttempt(currentPractice, book.id, answer, correct);
    recordStudyEvent({
      kind: "knowledge-review",
      at: Date.now(),
      bookId: book.id,
      nodeId: currentPractice.nodeId,
      correct,
    });
  };

  const movePractice = () => {
    if (!practiceItems.length) return;
    setPracticeIndex((current) => (current + 1) % practiceItems.length);
    setAnswer("");
    setFeedback(null);
    setFeedbackCorrect(null);
  };

  // —— 页面渲染：每一页都是一张固定版面的纸，内容超出时自动缩排 ——
  const renderPage = (page: BookPage | undefined): ReactNode => {
    if (!page || page.kind === "blank") {
      return <div className="book-page book-page--blank" />;
    }
    const fitKey = `${book.id}/${pageIdentity(page)}`;

    if (page.kind === "cover") {
      return (
        <div className="book-page">
          <div className="book-page__body">
            <div className="page-fit page-fit--center" data-fit={fitKey}>
              <div className="endpaper">
                <span className="endpaper__glyph" aria-hidden>
                  ❦
                </span>
                <p className="endpaper__title">{book.zhTitle}</p>
                <p className="endpaper__note">翻开这一本，一页一页读下去</p>
              </div>
            </div>
          </div>
        </div>
      );
    }

    if (page.kind === "toc") {
      return (
        <div className="book-page">
          <div className="book-page__body">
            <div className="page-fit page-fit--center" data-fit={fitKey}>
              <header className="toc-page__head">
                <span className="toc-page__chapter-no">Contents</span>
                <h1>{book.title}</h1>
                <p>{book.zhTitle}</p>
              </header>
              <div className="toc-page__label">
                <span>目录</span>
                <small>
                  {page.part} / {page.parts}
                </small>
              </div>
              <nav className="toc-page__chapters" aria-label="章节目录">
                {page.moduleIds.map((id) => {
                  const module = moduleById(id);
                  if (!module) return null;
                  const index = book.modules.findIndex(
                    (entry) => entry.id === id,
                  );
                  return (
                    <button
                      type="button"
                      key={id}
                      className={cn(module.id === selectedModule?.id && "is-active")}
                      onClick={() => jumpToChapter(id)}
                    >
                      <span className="toc-page__index">{pad2(index + 1)}</span>
                      <span className="toc-page__name">
                        <strong>{module.title}</strong>
                        <small>{module.titleZh}</small>
                      </span>
                    </button>
                  );
                })}
              </nav>
            </div>
          </div>
        </div>
      );
    }

    if (page.kind === "chapter") {
      const module = moduleById(page.moduleId);
      if (!module) return <div className="book-page book-page--blank" />;
      const index = book.modules.findIndex((entry) => entry.id === module.id);
      return (
        <div className="book-page">
          <div className="book-page__body">
            <div className="page-fit page-fit--center" data-fit={fitKey}>
              <header className="toc-page__head">
                <span className="toc-page__chapter-no">
                  Chapter {pad2(index + 1)}
                </span>
                <h1>{module.title}</h1>
                <p>{module.titleZh}</p>
              </header>
              <div className="toc-page__label">
                <span>本章小节</span>
                <small>{module.nodes.length} concepts</small>
              </div>
              <nav className="toc-page__nodes" aria-label="章内知识点">
                {module.nodes.map((node, nodeIndex) => {
                  const saved = bookCards.some((card) => card.nodeId === node.id);
                  return (
                    <button
                      type="button"
                      key={node.id}
                      className={cn(node.id === selectedNode?.id && "is-active")}
                      onClick={() => jumpToNode(module.id, node.id)}
                    >
                      <span className="toc-page__index">{pad2(nodeIndex + 1)}</span>
                      <span className="toc-page__name">
                        <strong>{node.title}</strong>
                        <small>{node.titleZh}</small>
                      </span>
                      {saved ? <Check size={13} /> : null}
                    </button>
                  );
                })}
              </nav>
            </div>
          </div>
        </div>
      );
    }

    if (page.kind === "read") {
      const data = readDataFor(page);
      const node = data.node;
      const reading = data.readingPage;
      const meta = `${data.safeIndex + 1} / ${Math.max(data.list.length, 1)}`;
      return (
        <div className="book-page">
          <header className="reading-head">
            <span className="reading-head__no">{pad2(data.nodeIndex + 1)}</span>
            <div className="reading-head__title">
              <h1>{node?.titleZh || node?.title}</h1>
              <p>{node?.title}</p>
            </div>
            <span className="reading-head__meta">{meta}</span>
          </header>
          <div className="book-page__body">
            <div className="page-fit" data-fit={fitKey}>
              <article className="reading-body">
                {reading?.kind === "detail" ? (
                  <>
                    {reading.continued ? (
                      <p className="reader-detail__cont">
                        接上页 · {reading.titleZh}
                      </p>
                    ) : (
                      <h2 className="reader-detail__title">{reading.titleZh}</h2>
                    )}
                    <div className="reader-detail__body">
                      {reading.bodyZh
                        .split(/\n+/)
                        .map((line) => line.trim())
                        .filter(Boolean)
                        .map((line, lineIndex) => (
                          <p
                            key={`${lineIndex}-${line.slice(0, 16)}`}
                            className={cn(
                              "reader-line",
                              lineIsSection(line) && "is-section",
                            )}
                            data-depth={lineDepth(line)}
                          >
                            {line}
                          </p>
                        ))}
                    </div>
                  </>
                ) : reading?.kind === "intro" ? (
                  <>
                    <section className="reader-block">
                      <h3 className="reader-block__label">
                        <span className="reader-block__glyph" aria-hidden>
                          ◆
                        </span>
                        Definition
                      </h3>
                      <p className="reader-block__lead">{node?.summaryZh}</p>
                    </section>
                    <section className="reader-block">
                      <h3 className="reader-block__label">Original Text</h3>
                      <p className="reader-block__quote">{node?.keyIdea}</p>
                    </section>
                  </>
                ) : (
                  <>
                    {node?.keyPoints.length ? (
                      <section className="reader-block">
                        <h3 className="reader-block__label">
                          Key points
                          {reading && reading.parts > 1
                            ? ` · ${reading.part + 1}/${reading.parts}`
                            : ""}
                        </h3>
                        <ul className="reader-block__points">
                          {node.keyPoints
                            .slice(
                              (reading?.part ?? 0) * OVERVIEW_POINTS_PER_PAGE,
                              ((reading?.part ?? 0) + 1) *
                                OVERVIEW_POINTS_PER_PAGE,
                            )
                            .map((point) => (
                              <li key={point}>{point}</li>
                            ))}
                        </ul>
                      </section>
                    ) : null}
                    {node?.terms.length &&
                    reading?.kind === "points" &&
                    reading.part === reading.parts - 1 ? (
                      <section className="reader-block reader-block--keywords">
                        <h3 className="reader-block__label">Keywords</h3>
                        <ul className="reader-block__keywords">
                          {node.terms.map((term) => (
                            <li key={term}>{term}</li>
                          ))}
                        </ul>
                      </section>
                    ) : null}
                  </>
                )}
              </article>
            </div>
          </div>
          <footer className="knowledge-book-foot">
            <button
              type="button"
              className="knowledge-book-save"
              onClick={() => {
                if (!node) return;
                const card = addNodeCard(book.id, node.id);
                if (!card) return;
                recordStudyEvent({
                  kind: "card-created",
                  at: Date.now(),
                  cardId: card.id,
                  categoryId: book.categoryId,
                });
              }}
            >
              <BookmarkPlus size={14} />
              收藏这一页
            </button>
            <span className="knowledge-book-foot__meta">
              {data.module
                ? `Chapter ${pad2(
                    Math.max(
                      0,
                      book.modules.findIndex(
                        (entry) => entry.id === data.module?.id,
                      ),
                    ) + 1,
                  )} · ${data.module.titleZh}`
                : ""}
            </span>
          </footer>
        </div>
      );
    }

    if (page.kind === "practice") {
      const module = moduleById(page.moduleId);
      const moduleIdx = book.modules.findIndex(
        (entry) => entry.id === page.moduleId,
      );
      return (
        <div className="book-page">
          <header className="reading-head">
            <span className="reading-head__no">{pad2(moduleIdx + 1)}</span>
            <div className="reading-head__title">
              <h1>练习</h1>
              <p>{module?.titleZh}</p>
            </div>
            <span className="reading-head__meta">
              {accuracy}% 正确 · {progress}% 掌握
            </span>
          </header>
          <div className="book-page__body">
            <div className="page-fit" data-fit={fitKey}>
              <section className="knowledge-book-exercise">
                {currentPractice ? (
                  <>
                    <header>
                      <span>
                        <Sparkles size={14} />第 {practiceIndex + 1} /{" "}
                        {practiceItems.length} 题
                      </span>
                      <small>{module?.title}</small>
                    </header>
                    <strong>{currentPractice.prompt}</strong>
                    {currentPractice.options.length ? (
                      <div className="knowledge-book-options">
                        {currentPractice.options.map((option) => (
                          <label key={option}>
                            <input
                              type="radio"
                              name={currentPractice.id}
                              checked={answer === option}
                              onChange={() => {
                                setAnswer(option);
                                setFeedback(null);
                                setFeedbackCorrect(null);
                              }}
                            />
                            <span>{option}</span>
                          </label>
                        ))}
                      </div>
                    ) : (
                      <input
                        value={answer}
                        onChange={(event) => {
                          setAnswer(event.target.value);
                          setFeedback(null);
                          setFeedbackCorrect(null);
                        }}
                        placeholder="Write your answer…"
                        onKeyDown={(event) => {
                          if (event.key === "Enter") submitPractice();
                        }}
                      />
                    )}
                    {feedback ? (
                      <p
                        className={cn(
                          "knowledge-book-feedback",
                          feedbackCorrect === false && "is-wrong",
                        )}
                      >
                        {feedback}
                      </p>
                    ) : null}
                    <div className="knowledge-book-exercise__actions">
                      {feedback ? (
                        <button type="button" onClick={movePractice}>
                          <RotateCcw size={14} />
                          下一题
                        </button>
                      ) : (
                        <button
                          type="button"
                          disabled={!answer.trim()}
                          onClick={submitPractice}
                        >
                          <CircleHelp size={14} />
                          检查答案
                        </button>
                      )}
                    </div>
                  </>
                ) : (
                  <p className="knowledge-book-empty">
                    这一章还没有练习题。翻到别的章节继续。
                  </p>
                )}
              </section>
            </div>
          </div>
          <footer className="knowledge-book-foot">
            {TRACK_BY_BOOK[book.id] ? (
              <button
                type="button"
                className="knowledge-book-save"
                onClick={() => navigate(`/drill/${TRACK_BY_BOOK[book.id]}`)}
              >
                去练习册做题
              </button>
            ) : null}
            <span className="knowledge-book-foot__meta">
              Chapter {pad2(moduleIdx + 1)} · {module?.titleZh}
            </span>
          </footer>
        </div>
      );
    }

    // notes：书末的知识卡片页。
    return (
      <div className="book-page">
        <header className="reading-head">
          <span className="reading-head__no">卡</span>
          <div className="reading-head__title">
            <h1>知识卡片</h1>
            <p>
              {selectedNode
                ? `正在读：${selectedNode.titleZh || selectedNode.title}`
                : "读完一页，随手写一张"}
            </p>
          </div>
          <span className="reading-head__meta">{bookNotes.length} 张</span>
        </header>
        <div className="book-page__body">
          <div className="page-fit" data-fit={fitKey}>
            <section className="knowledge-book-notes">
              <div className="knowledge-book-notes__composer">
                <textarea
                  value={noteDraft}
                  rows={3}
                  maxLength={480}
                  placeholder="这一页让你想到什么？写成一张卡片 —— 以后翻卡片就能回到这里。"
                  onChange={(event) => setNoteDraft(event.target.value)}
                  onKeyDown={(event) => {
                    if (
                      (event.metaKey || event.ctrlKey) &&
                      event.key === "Enter"
                    ) {
                      saveNote();
                    }
                  }}
                />
                <button
                  type="button"
                  disabled={!noteDraft.trim()}
                  onClick={saveNote}
                >
                  <BookmarkPlus size={14} />
                  记下这张卡片
                </button>
              </div>
              <PrismCarousel
                items={noteCards}
                activeIndex={Math.min(
                  noteIndex,
                  Math.max(0, noteCards.length - 1),
                )}
                onActiveChange={setNoteIndex}
                onSelect={(card) => {
                  const note = bookNotes.find((entry) => entry.id === card.id);
                  if (!note) return;
                  jumpToNode(note.moduleId, note.nodeId);
                }}
                emptyLabel="还没有卡片。读到有感觉的一页，在上面的框里写一句。"
              />
              {bookNotes.length ? (
                <button
                  type="button"
                  className="knowledge-book-notes__delete"
                  onClick={() => {
                    const note = bookNotes[noteIndex];
                    if (note) removeNote(note.id);
                  }}
                >
                  <Trash2 size={13} />
                  删除这一张
                </button>
              ) : null}
            </section>
          </div>
        </div>
      </div>
    );
  };

  return (
    <main
      className="book-stage"
      style={
        {
          "--book-accent": book.accent,
          "--book-secondary": book.secondary,
        } as CSSProperties
      }
    >
      <button
        type="button"
        className="book-stage__back"
        onClick={() => navigate(`/library/${book.categoryId}`)}
        aria-label="返回知识库"
      >
        <ArrowLeft size={17} />
      </button>

      <button
        type="button"
        className="book-stage__flip book-stage__flip--prev"
        onClick={() => beginTurn((single ? pageIndex : spread) - 1, -1)}
        disabled={phase === "closed" || (phase === "open" && safePos <= 0)}
        aria-label="上一页"
      >
        <ChevronLeft size={18} />
      </button>
      <button
        type="button"
        className="book-stage__flip book-stage__flip--next"
        onClick={() => beginTurn((single ? pageIndex : spread) + 1, 1)}
        disabled={phase === "back"}
        aria-label="下一页"
      >
        <ChevronRight size={18} />
      </button>

      {/* 打开的书：翻页时整张纸翻过去，左右两页都会换成新的一对 */}
      <div className="book-stage__scene">
        <div
          className={cn(
            "book3d",
            single && "book3d--single",
            phase === "closed" && !turn && "book3d--closed",
            phase === "back" && !turn && "book3d--closed-back",
            (phase === "open" || turn?.special === "close") && "book3d--opened",
          )}
          ref={bookRef}
        >
          {!single && (phase === "open" || turn?.special === "close") ? (
            <div className="book3d__spine" aria-hidden />
          ) : null}

          {/* 封面翻过去的这一下左页也要在：书是两栏网格，只挂右页的话它会被
              摆进左栏——右半边空着、目录跑到左边，翻完再「跳」回来。 */}
          {!single &&
          (phase === "open" ||
            turn?.special === "cover" ||
            turn?.special === "close" ||
            turn?.special === "reopen") ? (
            <section
              key={pageIdentity(staticLeftPage)}
              className="book3d__page book3d__page--left"
              aria-label="左页"
            >
              {renderPage(staticLeftPage)}
            </section>
          ) : null}

          {phase === "closed" && !turn ? (
            <button
              type="button"
              className="book-cover"
              onClick={openBook}
              aria-label="翻开封面"
            >
              {coverFace}
            </button>
          ) : null}
          {phase === "back" && !turn ? (
            <button
              type="button"
              className="book-cover book-cover--back"
              onClick={reopenFromBack}
              aria-label="再翻开这本书"
            >
              {backCoverFace}
            </button>
          ) : null}
          {phase === "open" || turn ? (
            <section
              key={pageIdentity(staticRightPage)}
              className="book3d__page book3d__page--right"
              aria-label="右页"
            >
              {renderPage(staticRightPage)}
            </section>
          ) : null}

          {turn ? (
            <div
              className={cn(
                "page-sheet",
                turn.dir === 1 ? "page-sheet--fwd" : "page-sheet--bwd",
              )}
              onAnimationEnd={(event) => {
                if (event.target === event.currentTarget) endTurn();
              }}
              aria-hidden
            >
              <div className="page-sheet__face page-sheet__face--front">
                {turn.special === "cover" ? coverFace : renderPage(faceFront)}
              </div>
              <div className="page-sheet__face page-sheet__face--back">
                {turn.special === "close" || turn.special === "reopen"
                  ? backCoverFace
                  : renderPage(faceBack)}
              </div>
            </div>
          ) : null}
        </div>
      </div>

      {/* 底部：回目录 + 当前章节 + 翻到第几页 */}
      <div className="book-stage__status">
        <button
          type="button"
          className="book-stage__toc"
          onClick={() => jumpToPosition(0)}
        >
          目录
        </button>
        <span className="book-stage__status-chapter">
          {selectedModule
            ? `Chapter ${pad2(chapterIndex + 1)} · ${selectedModule.titleZh}`
            : book.zhTitle}
        </span>
        <span className="book-stage__status-sep" aria-hidden />
        <button
          type="button"
          className="book-stage__status-count"
          onClick={() => {
            if (!faceFront && !turn) flipRef.current(1);
          }}
        >
          {safePos + 1} / {Math.max(totalLeaves, 1)}
        </button>
      </div>
    </main>
  );
}
