/**
 * 书页标注：高亮和笔记都挂在「选中的那段文字」上。
 *
 * 存的是段落下标加上这段文字在段落里的字符区间 —— 用户选中的可能只是半句，
 * 按句子存会把没选的部分也点亮。每段文字有一个规范形式（readerParagraphText），
 * 页面上渲染出来的 DOM 文本和它一字不差，选区换算出来的偏移才对得上。
 *
 * v1 存的是句子/单词级的固定键（sentence:0:2、word:0:1:4:phoneme），旧书第一次
 * 打开时按正文换算成区间，之后只认 v2。
 */
import { createId } from "./createId";
import { tokenizeReaderText } from "./readerWords";

export type ReaderHighlightColor = "yellow" | "blue" | "purple";

export interface ReaderAnnotation {
  id: string;
  /** null 表示只记了笔记，没有点亮颜色。 */
  color: ReaderHighlightColor | null;
  /** 选中的原文，用于抽屉便条和知识卡引用。 */
  text: string;
  /** 在段落规范文本里的区间，[start, end)。 */
  start: number;
  end: number;
  /** 我的理解。 */
  note?: string;
  createdAt: string;
}

export type ReaderAnnotations = Record<string, ReaderAnnotation[]>;

/** 三种颜色的含义固定，界面上直接用这份文案，避免各处自己写一套。 */
export const READER_HIGHLIGHT_COLORS: Array<{
  id: ReaderHighlightColor;
  label: string;
  zh: string;
}> = [
  { id: "yellow", label: "重要知识", zh: "重点" },
  { id: "blue", label: "概念定义", zh: "概念" },
  { id: "purple", label: "自己的疑问", zh: "疑问" },
];

const STORAGE_PREFIX = "leafia.reader.annotations.v2.";
const LEGACY_STORAGE_PREFIX = "leafia.reader.annotations.";

export function readerParagraphText(paragraph: string) {
  return splitReaderSentences(paragraph).join(" ");
}

function normalizeAnnotation(value: unknown): ReaderAnnotation | null {
  if (!value || typeof value !== "object") return null;
  const candidate = value as Partial<ReaderAnnotation>;
  if (
    typeof candidate.id !== "string" ||
    typeof candidate.text !== "string" ||
    typeof candidate.start !== "number" ||
    typeof candidate.end !== "number" ||
    !Number.isFinite(candidate.start) ||
    !Number.isFinite(candidate.end) ||
    candidate.end <= candidate.start
  ) {
    return null;
  }
  const color =
    candidate.color === "yellow" ||
    candidate.color === "blue" ||
    candidate.color === "purple"
      ? candidate.color
      : null;
  const note = typeof candidate.note === "string" && candidate.note ? candidate.note : undefined;
  if (!color && !note) return null;
  return {
    id: candidate.id,
    color,
    text: candidate.text,
    start: Math.max(0, Math.floor(candidate.start)),
    end: Math.max(0, Math.floor(candidate.end)),
    note,
    createdAt:
      typeof candidate.createdAt === "string"
        ? candidate.createdAt
        : new Date(0).toISOString(),
  };
}

export function normalizeReaderAnnotations(value: unknown): ReaderAnnotations {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  const annotations: ReaderAnnotations = {};
  for (const [key, list] of Object.entries(value as Record<string, unknown>)) {
    if (!Array.isArray(list)) continue;
    const entries = list
      .map(normalizeAnnotation)
      .filter((entry): entry is ReaderAnnotation => entry !== null)
      .sort((a, b) => a.start - b.start);
    if (entries.length > 0) annotations[key] = entries;
  }
  return annotations;
}

/**
 * 打开一本书时的标注。有 v2 就以 v2 为准（哪怕是空对象，说明用户清过），
 * 没有 v2 才拿旧版数据做一次迁移，并把迁移结果直接落盘。
 */
export function loadReaderAnnotations(
  bookId: string,
  paragraphs?: string[],
): ReaderAnnotations {
  if (typeof localStorage === "undefined") return {};
  const stored = localStorage.getItem(`${STORAGE_PREFIX}${bookId}`);
  if (stored !== null) {
    try {
      return normalizeReaderAnnotations(JSON.parse(stored));
    } catch {
      return {};
    }
  }
  if (!paragraphs || paragraphs.length === 0) return {};
  const migrated = migrateLegacyAnnotations(bookId, paragraphs);
  if (Object.keys(migrated).length > 0) saveReaderAnnotations(bookId, migrated);
  return migrated;
}

export function saveReaderAnnotations(
  bookId: string,
  annotations: ReaderAnnotations,
) {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(
      `${STORAGE_PREFIX}${bookId}`,
      JSON.stringify(annotations),
    );
  } catch {
    // 隐私模式写不进去，页面上的标注这一小段时间照常显示。
  }
}

export function paragraphAnnotations(
  annotations: ReaderAnnotations,
  paragraphIndex: number,
): ReaderAnnotation[] {
  return annotations[String(paragraphIndex)] ?? [];
}

/** 落在某个字符位置上的标注（区间是左闭右开，末尾不算）。 */
export function annotationAtOffset(
  annotations: ReaderAnnotations,
  paragraphIndex: number,
  offset: number,
): ReaderAnnotation | null {
  return (
    paragraphAnnotations(annotations, paragraphIndex).find(
      (annotation) => offset >= annotation.start && offset < annotation.end,
    ) ?? null
  );
}

export function annotationsByColor(
  annotations: ReaderAnnotations,
): Record<ReaderHighlightColor | "note", number> {
  const counts = { yellow: 0, blue: 0, purple: 0, note: 0 };
  for (const list of Object.values(annotations)) {
    for (const annotation of list) {
      if (annotation.color) counts[annotation.color] += 1;
      if (annotation.note) counts.note += 1;
    }
  }
  return counts;
}

/**
 * 把旧标注从「新范围里挖掉」：完全盖住的丢掉，压到边的截短，
 * 整个包住新范围的断成两截（笔记跟在前半截上）。
 */
function subtractRange(
  annotation: ReaderAnnotation,
  range: { start: number; end: number },
): ReaderAnnotation[] {
  if (annotation.end <= range.start || annotation.start >= range.end) {
    return [annotation];
  }
  const pieces: ReaderAnnotation[] = [];
  if (annotation.start < range.start) {
    pieces.push({ ...annotation, end: range.start });
  }
  if (annotation.end > range.end) {
    const tail = { ...annotation, start: range.end };
    if (pieces.length > 0) {
      // 断成两截时，笔记只留在前半截上。
      tail.id = createId();
      tail.note = undefined;
    }
    pieces.push(tail);
  }
  return pieces;
}

export function insertReaderAnnotation(
  annotations: ReaderAnnotations,
  paragraphIndex: number,
  annotation: ReaderAnnotation,
): ReaderAnnotations {
  const key = String(paragraphIndex);
  const next = paragraphAnnotations(annotations, paragraphIndex)
    .flatMap((existing) => subtractRange(existing, annotation))
    .filter((existing) => existing.end > existing.start);
  next.push(annotation);
  next.sort((a, b) => a.start - b.start);
  return { ...annotations, [key]: next };
}

export function removeReaderAnnotation(
  annotations: ReaderAnnotations,
  paragraphIndex: number,
  id: string,
): ReaderAnnotations {
  const key = String(paragraphIndex);
  const next = paragraphAnnotations(annotations, paragraphIndex).filter(
    (annotation) => annotation.id !== id,
  );
  if (next.length === 0) {
    const rest = { ...annotations };
    delete rest[key];
    return rest;
  }
  return { ...annotations, [key]: next };
}

export function updateReaderAnnotation(
  annotations: ReaderAnnotations,
  paragraphIndex: number,
  id: string,
  patch: Partial<Pick<ReaderAnnotation, "color" | "note" | "text">>,
): ReaderAnnotations {
  const key = String(paragraphIndex);
  const next = paragraphAnnotations(annotations, paragraphIndex)
    .map((annotation) => {
      if (annotation.id !== id) return annotation;
      const updated = { ...annotation, ...patch };
      if ("note" in patch) {
        updated.note = patch.note?.trim() || undefined;
      }
      return updated;
    })
    .filter((annotation) => annotation.color !== null || annotation.note);
  if (next.length === 0) {
    const rest = { ...annotations };
    delete rest[key];
    return rest;
  }
  return { ...annotations, [key]: next };
}

function legacySentences(paragraph: string) {
  let cursor = 0;
  return splitReaderSentences(paragraph).map((sentence) => {
    const start = cursor;
    cursor += sentence.length + 1;
    return { sentence, start };
  });
}

/**
 * 旧版标注（句子级、单词级）换算成区间。
 * 认得出的只有句子、单词和它们的下划线/高亮类型，别的一律丢弃 ——
 * 界面已经不再按「句子模式/单词模式」画标注，留着没有意义。
 */
export function migrateLegacyAnnotations(
  bookId: string,
  paragraphs: string[],
): ReaderAnnotations {
  if (typeof localStorage === "undefined") return {};
  let parsed: unknown;
  try {
    parsed = JSON.parse(
      localStorage.getItem(`${LEGACY_STORAGE_PREFIX}${bookId}`) ?? "null",
    );
  } catch {
    return {};
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};

  const annotations: ReaderAnnotations = {};
  for (const [key, type] of Object.entries(parsed as Record<string, unknown>)) {
    if (type !== "underline" && type !== "highlight" && type !== "sentence") {
      continue;
    }
    const parts = key.split(":");
    if (parts[0] !== "sentence" && parts[0] !== "word") continue;
    const paragraphIndex = Number(parts[1]);
    const paragraph = paragraphs[paragraphIndex];
    if (!paragraph) continue;
    const text = readerParagraphText(paragraph);
    const sentences = legacySentences(paragraph);
    const sentenceIndex = Number(parts[2]);
    const sentence = sentences[sentenceIndex];
    if (!sentence) continue;

    const color: ReaderHighlightColor =
      type === "underline" ? "blue" : "yellow";
    let start = sentence.start;
    let end = sentence.start + sentence.sentence.length;

    if (parts[0] === "word") {
      const tokenIndex = Number(parts[3]);
      const tokens = tokenizeReaderText(sentence.sentence);
      const token = tokens[tokenIndex];
      if (!token?.isWord) continue;
      let offset = sentence.start;
      for (let index = 0; index < tokenIndex; index += 1) {
        offset += tokens[index]?.value.length ?? 0;
      }
      start = offset;
      end = offset + token.value.length;
    }
    if (end > text.length || start >= end) continue;

    const key2 = String(paragraphIndex);
    const list = annotations[key2] ?? [];
    list.push({
      id: `legacy-${createId()}`,
      color,
      text: text.slice(start, end),
      start,
      end,
      createdAt: new Date().toISOString(),
    });
    list.sort((a, b) => a.start - b.start);
    annotations[key2] = list;
  }
  return annotations;
}

export function splitReaderSentences(paragraph: string) {
  const matches = paragraph.match(/[^.!?]+[.!?]?/g) ?? [paragraph];
  return matches.map((sentence) => sentence.trim()).filter(Boolean);
}
