import { useParams } from "react-router-dom";
import { knowledgeBookById } from "../knowledge/knowledgeCatalog";
import { KnowledgeBookPage } from "../knowledge/KnowledgeBookPage";
import { BookReaderPage } from "./BookReaderPage";

/**
 * 书籍路由的分派器：知识库教材走 KnowledgeBookPage，其余走沉浸式阅读器。
 *
 * 单独成一个模块是为了让 App 用 lazy() 引它——knowledgeCatalog 里装着全部
 * 教材章节（几十万字的正文），它和两个阅读器都不该在开场幕布播放前被解析。
 */
export default function BookRoute() {
  const { bookId } = useParams();
  if (knowledgeBookById(bookId)) return <KnowledgeBookPage />;
  return <BookReaderPage />;
}
