import { BOOKS, type BookDefinition, type BookId } from "../components/study/books";
import { createId } from "./createId";

const STORAGE_KEY = "leafia.custom-reader-books.v1";

export interface ReaderBook extends BookDefinition {
  custom?: boolean;
  createdAt?: string;
}

export interface ImportedReaderBook {
  title: string;
  author?: string;
  text: string;
}

export function readCustomBooks(): ReaderBook[] {
  if (typeof localStorage === "undefined") return [];
  try {
    const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function writeCustomBooks(books: ReaderBook[]) {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(STORAGE_KEY, JSON.stringify(books));
}

export function createCustomReaderBook(input: ImportedReaderBook): ReaderBook {
  const id = `custom-${createId()}` as BookId;
  const now = new Date().toISOString();
  return {
    id,
    title: input.title || "Imported Book",
    zhTitle: "导入书籍",
    author: input.author || "Imported",
    spine: "#7a563b",
    pageTint: "#f7efe2",
    slot: [0, 0],
    coverWidth: 0.19,
    height: 0.24,
    thickness: 0.04,
    lean: 0,
    editable: true,
    source: input.text,
    translation: "",
    custom: true,
    createdAt: now,
  };
}

export function addCustomReaderBook(input: ImportedReaderBook) {
  const book = createCustomReaderBook(input);
  writeCustomBooks([book, ...readCustomBooks()]);
  return book;
}

export function allReaderBooks() {
  return [...BOOKS, ...readCustomBooks()];
}

export function readerBookById(id: string) {
  return allReaderBooks().find((book) => book.id === id);
}

export function removeCustomReaderBook(id: string) {
  writeCustomBooks(readCustomBooks().filter((book) => book.id !== id));
}
