/**
 * 知识卡片的落盘层。
 *
 * 「书本知识可以记录笔记」：在知识书里读到一个知识点，随手写一张卡片，
 * 卡片归到那本书 + 那一节下面。和便条一样先落在本机（localStorage），
 * 没有账号也能用；卡片是照着某个 node 写的，所以点卡片能跳回那一页。
 */
export interface KnowledgeNote {
  id: string;
  bookId: string;
  moduleId: string;
  nodeId: string;
  /** 卡片上那行标题：写的时候用节点名预填，可改。 */
  title: string;
  body: string;
  createdAt: number;
}

export const KNOWLEDGE_NOTES_STORAGE_KEY = "leafia:knowledge-notes:v1";

type NotesByBook = Record<string, KnowledgeNote[]>;

function isNote(value: unknown): value is KnowledgeNote {
  if (!value || typeof value !== "object") return false;
  const note = value as Partial<KnowledgeNote>;
  return (
    typeof note.id === "string" &&
    typeof note.bookId === "string" &&
    typeof note.body === "string" &&
    typeof note.createdAt === "number"
  );
}

export function loadKnowledgeNotes(): NotesByBook {
  if (typeof localStorage === "undefined") return {};
  try {
    const raw = localStorage.getItem(KNOWLEDGE_NOTES_STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const out: NotesByBook = {};
    for (const [bookId, value] of Object.entries(parsed)) {
      if (!Array.isArray(value)) continue;
      const notes = value.filter(isNote);
      if (notes.length) out[bookId] = notes;
    }
    return out;
  } catch {
    return {};
  }
}

export function saveKnowledgeNotes(notes: NotesByBook) {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(KNOWLEDGE_NOTES_STORAGE_KEY, JSON.stringify(notes));
  } catch {
    // 存不下就只留在内存里，下次再说。
  }
}

export function createKnowledgeNote(input: {
  bookId: string;
  moduleId: string;
  nodeId: string;
  title: string;
  body: string;
}): KnowledgeNote {
  return {
    id: `note-${Date.now().toString(36)}-${Math.random()
      .toString(36)
      .slice(2, 7)}`,
    createdAt: Date.now(),
    ...input,
  };
}
